//! Book of Knowledge properties of the hook's byte readers (#74), each against the owning
//! program's own code on generated bytes, not only on the real accounts `tests/layout.rs`
//! checks:
//!
//! - TLV-4: `mint::read_mint` reads a mint's authorities and transfer hook exactly as
//!   Token-2022's state code does, and `bind`'s gate (`check_mint`, then `read_mint`) accepts
//!   only bytes Token-2022 unpacks as a mint;
//! - TLV-5: `token_account::is_mid_transfer_data` is true only on a Token-2022 token account
//!   of the mint whose `transferring` flag Token-2022 reads as set;
//! - BR-1: `router::read_market` decodes exactly what `pipeline-client` encodes for the
//!   router's `Market`, and refuses short, foreign or over-full ones.
//!
//! Pure functions only: no program is loaded, so these need no SBF build.

#[path = "../../mint-rules/tests/bok_bytes/mod.rs"]
mod bok_bytes;

use bok_bytes::*;
use containment_hook::{mint, router, token_account};
use pipeline_client::Pubkey;
use proptest::prelude::*;
use spl_token_2022_interface::extension::transfer_hook::{TransferHook, TransferHookAccount};
use spl_token_2022_interface::extension::{BaseStateWithExtensions, StateWithExtensions};
use spl_token_2022_interface::state::{Account, Mint};
use std::sync::atomic::{AtomicU32, Ordering};

/// Token-2022's `Multisig::LEN`.
const MULTISIG_LEN: usize = 355;

fn bytes_of(key: Option<impl AsRef<[u8]>>) -> Option<[u8; 32]> {
    key.map(|key| key.as_ref().try_into().unwrap())
}

/// TLV-4, on every mint Token-2022 unpacks: the same authorities, and the same transfer hook
/// authority and program, an all-zero key read as none.
#[test]
fn tlv_4_read_mint_reads_what_token_2022_reads() {
    let hooks = AtomicU32::new(0);
    run_paired(mint_bytes(), |data| {
        let Ok(theirs) = StateWithExtensions::<Mint>::unpack(&data) else {
            return Ok(false);
        };
        let ours = mint::read_mint(&data);
        prop_assert!(
            ours.is_some(),
            "Token-2022 unpacks a mint read_mint refuses"
        );
        let ours = ours.unwrap();
        let authority: Option<Pubkey> = theirs.base.mint_authority.into();
        let freeze: Option<Pubkey> = theirs.base.freeze_authority.into();
        prop_assert_eq!(ours.mint_authority, bytes_of(authority.as_ref()));
        prop_assert_eq!(ours.freeze_authority, bytes_of(freeze.as_ref()));
        match theirs.get_extension::<TransferHook>() {
            Ok(hook) => {
                hooks.fetch_add(1, Ordering::Relaxed);
                let hook_authority: Option<Pubkey> = hook.authority.into();
                let hook_program: Option<Pubkey> = hook.program_id.into();
                let read = ours.transfer_hook;
                prop_assert!(read.is_some());
                let read = read.unwrap();
                prop_assert_eq!(read.authority, bytes_of(hook_authority.as_ref()));
                prop_assert_eq!(read.program, bytes_of(hook_program.as_ref()));
            }
            Err(_) => prop_assert_eq!(ours.transfer_hook, None),
        }
        Ok(true)
    });
    let hooks = hooks.into_inner();
    assert!(
        hooks >= CASES / 4,
        "only {hooks} mints carried a transfer hook"
    );
}

/// TLV-4, `bind`'s whole gate on mints whose base Token-2022 may refuse (an option tag other
/// than 0 or 1, an `is_initialized` byte other than 1): whatever `check_mint` and `read_mint`
/// both accept, Token-2022 unpacks as a mint.
#[test]
fn tlv_4_binds_gate_accepts_only_mints_token_2022_unpacks() {
    let (accepted, refused_base) = (AtomicU32::new(0), AtomicU32::new(0));
    proptest::test_runner::TestRunner::new(proptest::test_runner::Config::with_cases(PAIRED_CASES))
        .run(&loose_mint_bytes(), |data| {
            let gate = mint_rules::check_mint(&mint_rules::TOKEN_2022_PROGRAM_ID, &data).is_ok()
                && mint::read_mint(&data).is_some();
            let theirs = StateWithExtensions::<Mint>::unpack(&data).is_ok();
            if gate {
                accepted.fetch_add(1, Ordering::Relaxed);
                prop_assert!(theirs, "bind's gate accepts bytes Token-2022 refuses");
            } else if mint_rules::check_mint(&mint_rules::TOKEN_2022_PROGRAM_ID, &data).is_ok() {
                // check_mint alone passed a base Token-2022 refuses; read_mint caught it.
                refused_base.fetch_add(1, Ordering::Relaxed);
            }
            Ok(())
        })
        .unwrap();
    let (accepted, refused_base) = (accepted.into_inner(), refused_base.into_inner());
    assert!(
        accepted >= CASES / 4,
        "only {accepted} mints passed the gate"
    );
    println!("check_mint passed and read_mint refused {refused_base} bad bases");
}

/// TLV-5: `is_mid_transfer_data` is true only where Token-2022 unpacks a token account of
/// the mint with the flag set, and true wherever Token-2022 does with the flag written as
/// Token-2022 writes it (1). Another mint's key never matches.
#[test]
fn tlv_5_the_transferring_flag_is_token_2022s() {
    let (set, wide) = (AtomicU32::new(0), AtomicU32::new(0));
    run_paired(account_bytes(), |(mint_key, data)| {
        let mint = anchor_lang::prelude::Pubkey::new_from_array(mint_key);
        let ours = token_account::is_mid_transfer_data(&data, &mint);
        // Token-2022 refuses any account of a multisig's length (355 bytes) and never gives
        // an account with extensions that length (`adjust_len_for_multisig` adds two bytes);
        // the hook refuses that length too (hardening finding H034 of #74).
        if data.len() == MULTISIG_LEN {
            prop_assert!(!ours, "a flag read on an account of a multisig's length");
            return Ok(false);
        }
        let Ok(state) = StateWithExtensions::<Account>::unpack(&data) else {
            prop_assert!(
                !ours,
                "a flag read on bytes Token-2022 does not unpack as an account"
            );
            return Ok(false);
        };
        prop_assert_eq!(state.base.mint.to_bytes(), mint_key);
        let flag = state
            .get_extension::<TransferHookAccount>()
            .ok()
            .map(|ext| (bool::from(&ext.transferring), ext.transferring.0));
        match flag {
            Some((true, 1)) => {
                set.fetch_add(1, Ordering::Relaxed);
                prop_assert!(ours, "Token-2022 reads the flag set and the hook does not");
            }
            Some((true, _)) => {
                // A byte Token-2022 never writes, read as set by its PodBool: the hook
                // refuses it (fails closed).
                wide.fetch_add(1, Ordering::Relaxed);
                prop_assert!(!ours);
            }
            _ => prop_assert!(!ours, "the hook reads a flag Token-2022 reads as unset"),
        }
        let mut other = mint_key;
        other[0] ^= 1;
        prop_assert!(!token_account::is_mid_transfer_data(
            &data,
            &anchor_lang::prelude::Pubkey::new_from_array(other)
        ));
        Ok(true)
    });
    let (set, wide) = (set.into_inner(), wide.into_inner());
    assert!(set >= CASES / 20, "only {set} accounts had the flag set");
    println!("{wide} accounts carried a flag byte above 1, refused by the hook");
}

/// TLV-5: a mint's bytes are never a token account mid-transfer, even when its first 32
/// bytes are taken as the mint key.
#[test]
fn tlv_5_a_mint_is_never_mid_transfer() {
    run_paired(mint_bytes(), |data| {
        if data.get(ACCOUNT_LEN) != Some(&1) {
            return Ok(false);
        }
        let key: [u8; 32] = data[..32].try_into().unwrap();
        prop_assert!(!token_account::is_mid_transfer_data(
            &data,
            &anchor_lang::prelude::Pubkey::new_from_array(key)
        ));
        Ok(true)
    });
}

fn market() -> impl Strategy<Value = pipeline_client::Market> {
    let key = || any::<[u8; 32]>().prop_map(Pubkey::new_from_array);
    (
        (
            key(),
            key(),
            prop_oneof![8 => 0u8..=4, 1 => 5u8..=8, 1 => any::<u8>()],
        ),
        (
            proptest::array::uniform4(key()),
            proptest::array::uniform4(key()),
        ),
        (any::<bool>(), key(), any::<i64>()),
        (any::<u8>(), any::<u8>(), any::<u8>()),
    )
        .prop_map(
            |(
                (strategy_program, market_state, mint_count),
                (mints, vaults),
                (supports_exact_out, created_by, created_at),
                (bump, fee_authority_bump, fee_mint_index),
            )| pipeline_client::Market {
                strategy_program,
                market_state,
                mint_count,
                mints,
                vaults,
                supports_exact_out,
                created_by,
                created_at,
                bump,
                fee_authority_bump,
                fee_mint_index,
            },
        )
}

fn encoded(market: &pipeline_client::Market) -> Vec<u8> {
    let mut data = pipeline_client::account_discriminator("Market").to_vec();
    data.extend(borsh::to_vec(market).unwrap());
    data
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(CASES))]

    /// BR-1: every field the hook reads round-trips, any trailing bytes change nothing, and a
    /// mint count above four is refused.
    #[test]
    fn br_1_read_market_decodes_what_pipeline_client_encodes(
        market in market(),
        trailing in proptest::collection::vec(any::<u8>(), 0..8),
    ) {
        let mut data = encoded(&market);
        prop_assert_eq!(data.len(), 373);
        let decoded = pipeline_client::decode_market(&data);
        prop_assert_eq!(decoded.as_ref(), Some(&market));
        data.extend(trailing);
        let ours = router::read_market(&data);
        if market.mint_count as usize > 4 {
            prop_assert!(ours.is_none());
            return Ok(());
        }
        let ours = ours.expect("a router Market");
        let ck = |key: &anchor_lang::prelude::Pubkey| Pubkey::new_from_array(key.to_bytes());
        prop_assert_eq!(ck(&ours.strategy), market.strategy_program);
        prop_assert_eq!(ck(&ours.market_state), market.market_state);
        prop_assert_eq!(ours.mint_count, market.mint_count);
        prop_assert_eq!(ours.mints.map(|k| ck(&k)), market.mints);
        prop_assert_eq!(ours.vaults.map(|k| ck(&k)), market.vaults);
        prop_assert_eq!(ours.bump, market.bump);
        prop_assert_eq!(ours.fee_authority_bump, market.fee_authority_bump);
        prop_assert_eq!(
            ours.mints().iter().map(ck).collect::<Vec<_>>(),
            market.mints().to_vec()
        );
    }

    /// BR-1: shorter than the fields the hook reads, or another account's discriminator, is
    /// refused.
    #[test]
    fn br_1_read_market_refuses_short_or_foreign_accounts(
        market in market(),
        cut in 0usize..372,
        flip in 0usize..8,
    ) {
        let data = encoded(&market);
        prop_assert!(router::read_market(&data[..cut]).is_none());
        let mut foreign = data.clone();
        foreign[flip] ^= 0x01;
        prop_assert!(router::read_market(&foreign).is_none());
    }
}
